export function getWordBank(language,lesson,category,lessons){
 if(lesson==='home')return lessons[language].home;
 if(category==='space')return lessons[language].words;
 if(category==='mixed')return [...new Set([...lessons[language].words,...categories.flatMap(c=>c[language])])];
 return categories.find(c=>c.id===category)?.[language]||lessons[language].words;
}
export function shuffled(words,random=Math.random){const copy=[...words];for(let i=copy.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]];}return copy;}
